# hash variants of token
for name,fn in [('md5',hashlib.md5),('sha1',hashlib.sha1),('sha256',hashlib.sha256)]:
    for s in [tok, tok.replace('dt_live_',''), 'b8d8a6d11ea441a488bb']:
        cands.add(fn(s.encode()).hexdigest())
# base64 variants
import base64
for s in [tok, 'b8d8a6d11ea441a488bb']:
    cands.add(base64.b64encode(s.encode()).decode())
    cands.add(base64.b64encode(s.encode()).decode().rstrip('=')
)
