for a in ['X','x','pk','PRICING','pricing','svc','live','staging']:
    for b in [tok,'b8d8a6d11ea441a488bb','5404270b6a6b','3e675d8e']:
        cands.add(f'{a}_{b}'); cands.add(f'{a}-{b}'); cands.add(f'{a}{b}')
