# Common formats: hex(32), hex(40), uuid, base64url(24+), "svc_"/"pricing_"/"pr_"/"pk_"/"live_"/"key_" prefixed
import itertools, string, uuid, base64, random
cands=set()
seeds=['pricing','price','internal','live','staging','prod','deploy','token','key','secret','api','svc','service','v2','corp','gateway','b8d8a6d11ea441a488bb','a488bb','3e675d8e','cb8920709a86','5404270b6a6b']
